package com.parcelstationx.ui.frame;
import javax.swing.*; import java.awt.*; import java.util.LinkedHashMap; import java.util.Map;
public final class MainFrame extends JFrame { private final CardLayout cards=new CardLayout(); private final JPanel content=new JPanel(cards); public MainFrame() { super("ParcelStationX - 社区快递驿站"); Map<String,String> pages=new LinkedHashMap<>(); pages.put("首页","Dashboard"); pages.put("快件入库","Inbound"); pages.put("在库快件","Inventory"); pages.put("快件出库","Outbound"); pages.put("客户管理","Customers"); pages.put("货架管理","Shelves"); pages.put("员工管理","Users"); pages.put("操作日志","Logs"); JPanel nav=new JPanel(new GridLayout(0,1,4,4)); for (var entry:pages.entrySet()) { content.add(new JLabel(entry.getKey()+" 页面", SwingConstants.CENTER),entry.getValue()); JButton button=new JButton(entry.getKey()); button.addActionListener(e->cards.show(content,entry.getValue())); nav.add(button); } add(nav,BorderLayout.WEST); add(content,BorderLayout.CENTER); setSize(1000,650); setLocationRelativeTo(null); setDefaultCloseOperation(EXIT_ON_CLOSE); } }
